import ctypes
import os

# Create a large bytes object of zeros
n = 1000000
b = bytes(n)

# Get the address of the buffer
# In CPython, a bytes object has:
# Py_ssize_t ob_refcnt;
# PyTypeObject *ob_type;
# Py_ssize_t ob_size;
# Py_hash_t ob_shash;
# char ob_sval[1];

# So data starts at offset 32 on 64-bit systems
addr = id(b) + 32
ctypes.memmove(addr, b"a" * n, n)
print(b[:10])
